// collide() only sees where a boid
// ends its move, so a fast boid can
// jump clean over a 6 px wall.

if (crossed(from_x, from_y, self, w)) {
  self.x = from_x;
  self.y = from_y;
  bounce(self, w);
}

if (world->pointer_inside) {
  // steer along the tangent
  self.vx += -dy / distance * 0.6f;
  self.vy +=  dx / distance * 0.6f;
}

